// ------------------------------------------------------------------
// GRADES 10, 11, 12 — built from Grade 9 with progressive difficulty
// ------------------------------------------------------------------
function buildHigherGrade(baseGrade: GradeSpec, num: number): GradeSpec {
  const labels: Record<number, string> = { 10: 'Integrated Systems', 11: 'Professional Skills', 12: 'Capstone & Innovation' };
  const descs: Record<number, string> = {
    10: 'Integrate electronics, robotics, IoT and AI into complete intelligent systems.',
    11: 'Professional-grade embedded systems, cloud AI, full-stack development and product design.',
    12: 'Capstone projects integrating all skills with research methodology and innovation leadership.',
  };
  return {
    number: num,
    name: `Class ${num}`,
    level_label: labels[num],
    description: descs[num],
    modules: baseGrade.modules.map(m => ({
      ...m,
      slug: m.slug.replace('-9', `-${num}`),
      chapters: m.chapters.map(ch => ({
        ...ch,
        title: `${num === 10 ? 'Applied' : num === 11 ? 'Pro' : 'Capstone'}: ${ch.title}`,
        difficulty: (num >= 11 ? 'advanced' : ch.difficulty === 'beginner' ? 'intermediate' : ch.difficulty) as 'beginner' | 'intermediate' | 'advanced',
        est: Math.min(ch.est + (num - 9) * 5, 90),
        summary: ch.summary + ` (Class ${num} depth: ${num === 10 ? 'applied projects' : num === 11 ? 'professional implementation' : 'original capstone research'})`,
      }))
    }))
  };
}

export const grade10 = buildHigherGrade(grade9, 10);
export const grade11 = buildHigherGrade(grade9, 11);
export const grade12 = buildHigherGrade(grade9, 12);
